import{_ as s,C as r,o as l,c as n,j as d,a as c,E as t,ak as a}from"./chunks/framework.DxrHb2fb.js";const P=JSON.parse('{"title":"MessageFeed 消息流","description":"","frontmatter":{},"headers":[],"relativePath":"components/message-feed.md","filePath":"components/message-feed.md","lastUpdated":1790414471000}'),h={name:"components/message-feed.md"},g={id:"messagefeed-消息流",tabindex:"-1"};function b(m,e,p,u,f,x){const i=r("Badge"),o=r("XhDemo");return l(),n("div",null,[d("h1",g,[e[0]||(e[0]=c("MessageFeed 消息流 ",-1)),t(i,{type:"info",text:"alpha"}),e[1]||(e[1]=c()),e[2]||(e[2]=d("a",{class:"header-anchor",href:"#messagefeed-消息流","aria-label":'Permalink to "MessageFeed 消息流 <Badge type="info" text="alpha" />"'},"​",-1))]),e[3]||(e[3]=a('<p>一段会话的消息序列：粘底跟随、条目集合语义、键盘遍历与一个统一的播报区。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/message-feed" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/message-feed.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/message-feed" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/message-feed" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/message-feed.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>消息内容全部由作者编写；组件管理的是集合语义、粘底与播报区</p>',4)),t(o,{src:"message-feed/01-basic"}),e[4]||(e[4]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;message-feed&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>list</code></strong> · <code>item</code> · <code>item-label</code> · <code>pending-indicator</code> · <code>scroll-to-end-trigger</code> · <code>live-region</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="粘底跟随与播报" tabindex="-1">粘底跟随与播报 <a class="header-anchor" href="#粘底跟随与播报" aria-label="Permalink to &quot;粘底跟随与播报&quot;">​</a></h3><p>新消息增长时自动到底部，向上翻即解除；一轮结束后在播报区朗读一句</p>',6)),t(o,{src:"message-feed/02-sticky"}),e[5]||(e[5]=d("h3",{id:"按角色分侧",tabindex:"-1"},[c("按角色分侧 "),d("a",{class:"header-anchor",href:"#按角色分侧","aria-label":'Permalink to "按角色分侧"'},"​")],-1)),e[6]||(e[6]=d("p",null,"条目上带 data-role，左右分侧与气泡在使用者一侧编写，组件不预设这层外观",-1)),t(o,{src:"message-feed/03-roles"}),e[7]||(e[7]=d("h3",{id:"运行态与播报",tabindex:"-1"},[c("运行态与播报 "),d("a",{class:"header-anchor",href:"#运行态与播报","aria-label":'Permalink to "运行态与播报"'},"​")],-1)),e[8]||(e[8]=d("p",null,"status 由宿主持有，组件只把它透出为 root 上的 data-state；已发送、等首个片段时列表之后的呼吸点亮起，首个片段一到就收；播报只发生在 live-region 中，一轮结束后才写入一句",-1)),t(o,{src:"message-feed/04-status"}),e[9]||(e[9]=d("h3",{id:"触底加载更多",tabindex:"-1"},[c("触底加载更多 "),d("a",{class:"header-anchor",href:"#触底加载更多","aria-label":'Permalink to "触底加载更多"'},"​")],-1)),e[10]||(e[10]=d("p",null,"stick-change 报告到达底部，宿主据此获取下一页；先向上翻一段再滚回底部，取回的消息接在后面",-1)),t(o,{src:"message-feed/05-load-more"}),e[11]||(e[11]=d("h3",{id:"向上加载更早的消息",tabindex:"-1"},[c("向上加载更早的消息 "),d("a",{class:"header-anchor",href:"#向上加载更早的消息","aria-label":'Permalink to "向上加载更早的消息"'},"​")],-1)),e[12]||(e[12]=d("p",null,"直接监听视口的滚动事件：滚到接近顶部时获取上一页，取回的消息插在最前面，正在阅读的位置不会被顶走",-1)),t(o,{src:"message-feed/06-load-earlier"}),e[13]||(e[13]=d("h3",{id:"跳到指定的一条",tabindex:"-1"},[c("跳到指定的一条 "),d("a",{class:"header-anchor",href:"#跳到指定的一条","aria-label":'Permalink to "跳到指定的一条"'},"​")],-1)),e[14]||(e[14]=d("p",null,"消息 id 就是锚点：Vue 侧使用 root 插槽提供的 scrollToItem / focusItem，自定义元素侧按同一个 id 取节点自行滚动",-1)),t(o,{src:"message-feed/07-scroll-to"}),e[15]||(e[15]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>AI 对话或聊天界面的消息列表。</li><li>内容从底部持续生长，需要始终跟随到底，但用户向上翻时不被拉回。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>内容不分条、只是持续追加的输出（运行日志、命令回显）时，使用<a href="./log">日志</a>。两者的粘底、回到底部与播报区是同一套，差别只在是否需要条目集合语义与逐条遍历。</li><li>只是一列静态卡片时，使用<a href="./list">列表</a>。</li><li>消息数以万计时，本组件不与<a href="./virtualizer">虚拟滚动</a>组合，键盘遍历要求条目都在活动 DOM 中；长会话请配合<a href="./infinite-scroll">无限滚动</a>分批加载并自行截断历史。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>粘底跟随：内容增高时自动到底，用户上滚即解除，滚回底部阈值内自动恢复。向上插入历史消息时补偿滚动位置，视口不跳动。</li><li>“回到底部”只判断是否在底部，不判断粘附意图：粘附中但内容尚未追上时按钮不显示。</li><li>整份消息列表只占一个 Tab 停靠位：<code>PageDown</code> / <code>PageUp</code> 在消息之间移动，<code>Ctrl+End</code> / <code>Ctrl+Home</code> 一步移到消息流之外（会话界面中通常是输入框）。</li><li>消息内容全部由作者编写：气泡、头像、时间、动作条都不是本组件的部件。</li><li>新生成的消息与出现的“回到底部”各带一段淡入位移；减弱动效由令牌层收敛，不需要另行关闭。</li><li>已发送、等首个片段（<code>status</code> 为 <code>submitted</code>）时，放在列表之后的 <code>pending-indicator</code> 显示为一颗呼吸的圆点，首个片段到来即收起；它只给视觉看，进度由宿主写进播报区。减弱动效下圆点静止。</li><li>“回到底部”留空时皮肤绘制向下的字形，放入节点即替换为自定义图形。</li><li>应用设为 <code>data-material=&quot;liquid&quot;</code> 时，“回到底部”换成液态面：按下层换色调，按住时液面随手指形变。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>正文使用<a href="./markdown-stream">流式正文</a>，代码使用<a href="./code-view">代码视图</a>。</li><li>每条消息的动作条使用<a href="./toolbar">工具栏</a>，复制使用<a href="./clipboard">剪贴板</a>。</li><li>加载更早的消息使用<a href="./infinite-scroll">无限滚动</a>，必须把消息流的滚动容器交给它，否则它的提前量只对窗口视口生效。</li><li>空会话使用<a href="./empty-state">空状态</a>，并显式把它的 <code>live</code> 设为 <code>off</code>：它默认会成为活动区域，放在消息流中会与播报区冲突。</li><li>需要左右分侧或气泡时，条目上带 <code>data-role</code>（<code>user</code> / <code>assistant</code> / <code>system</code>），在自己的样式表中按它编写 <code>align-self</code>、底色、内衬与最大行宽，组件不预设这层外观。</li><li>仍在流式写入的条目带 <code>data-streaming</code>，这是留给使用者的钩子：正文经<a href="./markdown-stream">流式正文</a>渲染时，光标就是“仍在写入”的标记；正文不经它渲染时，可按该属性自行添加非遮蔽式的标记，例如前导色条或标签态。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>条目必须是内容层的直接子节点：向上插入历史消息时的滚动补偿只在直接子节点中选锚点，套一层壳或使用 <code>display: contents</code> 都会让补偿静默失效。</li><li>一轮流式结束时把整段最终文本写入播报区，不每个 token 写一次。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>给每条消息各写 <code>tabindex=&quot;0&quot;</code>：两百条消息就是两百个 Tab 停靠位。</li><li>在消息流内再套一层滚动容器：粘底逻辑只识别本组件的视口，套一层后失效。</li><li>按 <code>data-streaming</code> 把整条消息压暗或虚化：一轮流式可能持续数分钟，被遮盖的正是读者正在逐字阅读的内容。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-message-feed&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMessageFeedItem</code> <code>XhMessageFeedItemLabel</code> <code>XhMessageFeedList</code> <code>XhMessageFeedLiveRegion</code> <code>XhMessageFeedPendingIndicator</code> <code>XhMessageFeedRoot</code> <code>XhMessageFeedScrollToEndTrigger</code> <code>XhMessageFeedViewport</code></td></tr><tr><td>组合式函数</td><td><code>useMessageFeed</code></td></tr><tr><td>状态机</td><td><code>messageFeedMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/message-feed.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>消息总数，由宿主声明，不从 DOM 统计；aria-setsize 取它。</td></tr><tr><td><code>status</code></td><td><code>MessageFeedStatus</code></td><td></td><td>本轮的运行态，只写 data-state，状态机不读取它。</td></tr><tr><td><code>threshold</code></td><td><code>number</code></td><td></td><td>距底部多少 px 视为在底部，默认使用贴底原语的默认值。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>到达首尾是否回绕，默认 false：会话是线性的。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;MessageFeedTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onStickChange</code></td><td><code>(details: MessageFeedStickChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onItemFocus</code></td><td><code>(details: MessageFeedItemFocusDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>stick-change</code></td><td><code>MessageFeedStickChangeDetails</code></td><td>贴底状态变化；detail 为 <code>{ atBottom: boolean, sticking: boolean }</code></td></tr><tr><td><code>item-focus</code></td><td><code>MessageFeedItemFocusDetails</code></td><td>锚点变化；detail 为 <code>{ id: string | null }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMessageFeedRoot</code></td><td><code>default</code></td><td><code>MessageFeedRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMessageFeedItem</code></td><td><code>itemId</code></td><td><code>string</code></td><td>是</td><td>该条消息的身份，写为 data-value；导航与锚点都以它为准。</td></tr><tr><td><code>XhMessageFeedItem</code></td><td><code>itemIndex</code></td><td><code>number | string</code></td><td>是</td><td>0 基下标，写为 aria-posinset = index + 1。</td></tr><tr><td><code>XhMessageFeedItem</code></td><td><code>itemRole</code></td><td><code>MessageFeedItemRole</code></td><td></td><td>该条消息的发言者。</td></tr><tr><td><code>XhMessageFeedItem</code></td><td><code>itemStreaming</code></td><td><code>boolean</code></td><td></td><td>该条仍在流式写入。</td></tr><tr><td><code>XhMessageFeedRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;MessageFeedRootSlotProps&gt;</code></td><td></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>props.status</td></tr><tr><td><code>pending-indicator</code></td><td>props.status</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td>&#39;hidden&#39; | &#39;visible&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>STICK.CHANGE</code> · <code>SCROLL_TO_BOTTOM</code> · <code>ITEM.FOCUS</code> · <code>FEED.BLUR</code> · <code>PRESS.START</code> · <code>PRESS.END</code> · <code>ARRIVALS.TRACKED</code> · <code>TRIGGER.RENDERED</code></p><p><strong>判据</strong>：<code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>MessageFeedStatus</code></td><td></td></tr><tr><td><code>atBottom</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>sticking</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>focusedId</code></td><td><code>string | null</code></td><td>roving tabindex 的锚点。</td></tr><tr><td><code>showScrollToEndTrigger</code></td><td><code>boolean</code></td><td>是否显示回到底部按钮：只判断是否在底部，不判断贴附意图。</td></tr><tr><td><code>scrollToBottom</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>scrollToItem</code></td><td><code>(id: string) =&gt; void</code></td><td>把某条消息滚进可视区；该条不在 DOM 中时不做任何事。</td></tr><tr><td><code>focusItem</code></td><td><code>(id: string) =&gt; void</code></td><td>把焦点落到某条消息上；该条不在 DOM 中时不做任何事。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: MessageFeedItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemLabelProps</code></td><td><code>(props: Pick&lt;MessageFeedItemProps, &#39;id&#39;&gt;) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getScrollToEndTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPendingIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>已发送、等首个片段时的呼吸点：status 为 submitted 时出现，对读屏隐藏。</td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/feed/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>PageDown</code></td><td>焦点在消息流内</td><td>焦点移到下一条消息；到末条时按 loop 决定回绕还是不动</td></tr><tr><td><code>PageUp</code></td><td>焦点在消息流内</td><td>焦点移到上一条消息；到首条时按 loop 决定回绕还是不动</td></tr><tr><td><code>Control+End</code></td><td>焦点在消息流内</td><td>焦点移到消息流之后的第一个可聚焦元素，会话界面里通常是输入框</td></tr><tr><td><code>Control+Home</code></td><td>焦点在消息流内</td><td>焦点移到消息流之前的最后一个可聚焦元素</td></tr><tr><td><code>Tab</code></td><td>焦点在消息流内外之间移动</td><td>整份消息列表只占一个 Tab 停靠位：没有锚点时由根容器认领并把焦点转投给第一条，有锚点时那一条认领、根容器让位</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowDown</code> / <code>Home</code> / <code>End</code></td><td>焦点落在某条消息上</td><td>组件不接管，浏览器滚动最近的可滚动祖先</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在回到底部按钮上</td><td>滚回底部并恢复粘附（原生按钮激活）</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>按住回到底部按钮且视口不在底部</td><td>按住期间 scroll-to-end-trigger 投影 data-pressed，与指针 :active 同一副按压面；抬起、失焦或回到底部（按钮收起）撤下</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>aria-label</code></td><td>translations?.feed</td></tr><tr><td><code>list</code></td><td><code>role</code></td><td>&#39;feed&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-label</code></td><td>undefined | itemLabel(item.index + 1, count ?? -1, item.role)</td></tr><tr><td><code>item</code></td><td><code>aria-labelledby</code></td><td>scope.partId(&#39;message-feed&#39;, <code>item-label:${item.id}</code>) | undefined</td></tr><tr><td><code>item</code></td><td><code>aria-posinset</code></td><td>item.index + 1</td></tr><tr><td><code>item</code></td><td><code>aria-setsize</code></td><td>props.count</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;article&#39;</td></tr><tr><td><code>pending-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>aria-label</code></td><td>translations?.scrollToBottom</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr></tbody></table><ul><li><code>role=feed</code> 配 <code>role=article</code>，带 <code>aria-posinset</code> / <code>aria-setsize</code>；总数由 <code>count</code> 声明，不从 DOM 计数，虚拟化或分页时 DOM 中的条数不等于会话长度。</li><li>集合语义落在内容层而不是最外层：<code>role=feed</code> 只识别 <code>role=article</code> 的子节点，而播报区与回到底部按钮都是最外层的子节点。最外层只作为 Tab 停靠点与键盘宿主。</li><li>播报使用独立的原子区域：一份会话只应有一个活动区域，每条消息各开一个会互相打断。</li><li>消息流本身不发 <code>aria-busy</code>：它会压制同一棵子树内播报区的播报。</li><li>等首个片段的呼吸点对读屏隐藏，不单靠动画表达状态。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/message-feed.css</code> 使用 <code>[data-scope=&quot;message-feed&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>props.status</td></tr><tr><td><code>list</code></td><td><code>data-instant</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-role</code></td><td>item.role</td></tr><tr><td><code>item</code></td><td><code>data-streaming</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>pending-indicator</code></td><td><code>data-state</code></td><td>props.status</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-state</code></td><td>&#39;hidden&#39; | &#39;visible&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-display</code></td><td>&#39;always&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-profile</code></td><td>&#39;floating&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-liquid</code></td><td>&#39;&#39;</td></tr><tr><td><code>scroll-to-end-trigger</code></td><td><code>data-xh-material</code></td><td>&#39;frosted&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-message-feed-gap</code></td><td><code>list</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_message-feed-gap</code></td><td>message-feed 的 list 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-icon-size</code></td><td><code>scroll-to-end-trigger</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_action-profile-glyph-size</code></td><td>message-feed 的 scroll-to-end-trigger 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-item-gap</code></td><td><code>item</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>message-feed 的 item 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-item-radius</code></td><td><code>item</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-surface</code></td><td>message-feed 的 item 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-label-fg</code></td><td><code>item-label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>message-feed 的 item-label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-label-font-size</code></td><td><code>item-label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-caption-size</code></td><td>message-feed 的 item-label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-p</code></td><td><code>list</code><br><code>pending-indicator</code></td><td><code>margin-block-end</code><br><code>margin-inline-start</code><br><code>padding</code></td><td><code>default</code></td><td><code>--xh-_message-feed-p</code></td><td>message-feed 的 list、pending-indicator 部件 margin-block-end、margin-inline-start、padding 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-pending-indicator-color</code></td><td><code>pending-indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>message-feed 的 pending-indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-pending-indicator-radius</code></td><td><code>pending-indicator</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-circle</code></td><td>message-feed 的 pending-indicator 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-pending-indicator-size</code></td><td><code>pending-indicator</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>message-feed 的 pending-indicator 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-bg</code></td><td><code>scroll-to-end-trigger</code></td><td><code>--xh-ink-surface</code><br><code>background-color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>xh-ink-surface</code></td><td><code>--xh-_material-bg</code><br><code>--xh-_material-bg-focus</code></td><td>message-feed 的 scroll-to-end-trigger 部件 --xh-ink-surface、background-color 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-bg-hover</code></td><td><code>scroll-to-end-trigger</code></td><td><code>background-color</code></td><td><code>disabled</code><br><code>hover</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code></td><td><code>--xh-_material-bg-hover</code></td><td>message-feed 的 scroll-to-end-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-border</code></td><td><code>scroll-to-end-trigger</code></td><td><code>border</code><br><code>border-color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_material-border</code></td><td>message-feed 的 scroll-to-end-trigger 部件 border、border-color 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-fg</code></td><td><code>scroll-to-end-trigger</code></td><td><code>color</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_material-fg</code></td><td>message-feed 的 scroll-to-end-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-inset</code></td><td><code>scroll-to-end-trigger</code></td><td><code>inset-block-end</code><br><code>inset-inline-end</code></td><td><code>default</code></td><td><code>--xh-space-4</code></td><td>message-feed 的 scroll-to-end-trigger 部件 inset-block-end、inset-inline-end 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-radius</code></td><td><code>scroll-to-end-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-circle</code></td><td>message-feed 的 scroll-to-end-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-shadow</code></td><td><code>scroll-to-end-trigger</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>disabled</code><br><code>focus-visible</code><br><code>hover</code><br><code>is(:active, [data-pressed])</code><br><code>loading</code><br><code>not([data-disabled])</code><br><code>not([data-loading])</code><br><code>pressed</code></td><td><code>--xh-_material-shadow</code></td><td>message-feed 的 scroll-to-end-trigger 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-message-feed-scroll-to-end-trigger-size</code></td><td><code>scroll-to-end-trigger</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code><br><code>xh-action-profile=floating</code></td><td><code>--xh-_action-profile-visual-size</code></td><td>message-feed 的 scroll-to-end-trigger 部件 block-size、inline-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：按压 · 状态 · 出现（锚定面板） · 出现（无锚定弹出） · 列表 · 循环（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-breathe</code> · <code>xh-breathe-halo</code> · <code>xh-item-in</code> · <code>xh-pop-in</code> · <code>xh-pop-out</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',61))])}const q=s(h,[["render",b]]);export{P as __pageData,q as default};
